package com.cfbenchmarks.obsi.cli;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.PrintStream;

/**
 * Command-line entry point. Results go to stdout as JSON; errors go to stderr as JSON.
 *
 * <p>Scaffold only: no calculation is implemented yet, so every invocation reports
 * {@code NOT_IMPLEMENTED} and exits with status 1. The CLI contract (arguments, output
 * schema, exit codes) is still open, see {@code docs/decisions.md}.
 */
public final class Main {

    static final int EXIT_NOT_IMPLEMENTED = 1;

    private static final ObjectMapper JSON = new ObjectMapper();

    private Main() {
    }

    public static void main(String[] args) {
        System.exit(run(args, System.out, System.err));
    }

    static int run(String[] args, PrintStream out, PrintStream err) {
        ObjectNode error = JSON.createObjectNode()
                .put("error", "NOT_IMPLEMENTED")
                .put("message", "OBSI calculation is not implemented yet");
        err.println(error.toString());
        err.flush();
        return EXIT_NOT_IMPLEMENTED;
    }
}

